      goal: g,
      eps,
      g: new Float64Array(NC).fill(Infinity),
      rhs: new Float64Array(NC).fill(Infinity),
      km: 0,
      sLast: s,
      heap: new Heap(),
      lethal: cm.lethal.slice(),
