/* ---- core/nn.js ---- */
/* ============================================================
   Small neural networks in plain JavaScript: the forward pass of the learned blocks whose weights the build inlines
   from src/models/*.json (MODELS). A 1D convolution over the lidar beams with circular padding, ReLU and sigmoid: a
   few thousand parameters, a fraction of a millisecond per scan. No training here (training/).
   ============================================================ */
// @code nn-forward | nnForward: the forward pass, one circular 1D convolution per layer
function nnForward(model, x, n) {
  // x: Float32Array of n positions × cin channels, channel-minor (x[pos * cin + c]); returns the last layer's output
  let cur = x,
    cin = model.layers[0].cin;
  for (const L of model.layers) {
    const {cout, k, w, b} = L,
      p = k >> 1,
      out = new Float32Array(n * cout);
    for (let i = 0; i < n; i++)
      for (let o = 0; o < cout; o++) {
        let s = b[o];
        for (let j = 0; j < k; j++) {
          const ii = (i + j - p + n) % n, // circular: beam 119 neighbours beam 0
            base = (o * cin + 0) * k + j;
          for (let c = 0; c < cin; c++) s += w[base + c * k] * cur[ii * cin + c];
        }
        out[i * cout + o] = L.act === 'relu' ? (s > 0 ? s : 0) : L.act === 'sigmoid' ? 1 / (1 + Math.exp(-s)) : s;
      }
    cur = out;
    cin = cout;
  }
  return cur;
}
// @end
// @code mlp-forward | mlpForward: a multilayer perceptron, dense layers with ReLU
function mlpForward(model, x) {
  let cur = x;
  for (const L of model.layers) {
    const {nin, nout, w, b} = L,
      out = new Float32Array(nout);
    for (let o = 0; o < nout; o++) {
      let s = b[o];
      const base = o * nin;
      for (let i = 0; i < nin; i++) s += w[base + i] * cur[i];
      out[o] = L.act === 'relu' ? (s > 0 ? s : 0) : L.act === 'tanh' ? Math.tanh(s) : s;
    }
    cur = out;
  }
  return cur;
}
// @end

/* ---- core/agents.js ---- */
/* ============================================================
   Step
   ============================================================ */
/* ============================================================
   Moving agents: lidar detection, tracking (constant-velocity Kalman filter),
   prediction, and an ST-graph speed planner that uses the predictions.
   The global path stays static; agents are handled at the trajectory level
   (path–velocity decomposition), with escalation to a replan when speed alone
   cannot resolve the conflict.
   ============================================================ */
const AG_PATH_CTL = ['pp', 'rwf', 'stanley', 'pid'];
function agInit() {
  return {
    tracks: [],
    nextId: 1,
    det: [],
    dynPts: [],
    staticPts: null,
    lastT: null,
    st: null,
    vlim: Infinity,
    vlimStop: Infinity,
    blockT: 0,
    lastAgentPlan: -99,
    yieldLog: {},
    egoPath: null
  };
}
const agOn = () => P.agents !== 'off';
const AG_ST_CTL = [...AG_PATH_CTL, 'mpc']; // controllers that follow the speed plan: path trackers as a speed cap, MPC as its reference
const stActive = () => AG_ST_CTL.includes(P.ctl) && P.spd === 'st' && agOn();
// A lidar hit is "explained" when the static map accounts for it
function agExplained(x, y) {
  const k = cellIdx(x, y);
  if (k < 0) return true;
  if (P.per === 'oracle') return S.cm.dist[k] < 0.25;
  const i = k % GW,
    j = (k / GW) | 0; // built map: only cells that have been occupied for a while count as static
  for (let dj = -1; dj <= 1; dj++)
    for (let di = -1; di <= 1; di++) {
      const ii = i + di,
        jj = j + dj;
      if (ii < 0 || jj < 0 || ii >= GW || jj >= GH) continue;
      if (S.lo[jj * GW + ii] > 2.0) return true;
    }
  return false;
}
// Detection: cluster unexplained hits over consecutive beams, reject clusters too large to be a person
function agDetect() {
  const A = S.agents,
    e = S.est,
    R = S.scan;
  A.det = [];
  A.dynPts = [];
  if (!R) return;
  const pts = new Array(NBEAM).fill(null);
  for (let k = 0; k < NBEAM; k++) {
    if (R[k] >= LMAX - 1e-3) continue;
    const a = e.th - Math.PI + (k * TAU) / NBEAM,
      x = e.x + R[k] * Math.cos(a),
      y = e.y + R[k] * Math.sin(a);
    if (!agExplained(x, y)) pts[k] = [x, y, k];
  }
  agCluster(pts, false);
}
// The previous scan as it would look from the current pose if everything stood still: its points moved by the
