        ddy = p.y - q.y,
        dd = hyp(ddx, ddy) || 1e-6,
        f = SF.A * Math.exp((p.r + q.r - dd) / SF.B);
      fx += (f * ddx) / dd;
      fy += (f * ddy) / dd;
